173	    for (size_t inTensorId = 0; inTensorId < inTensors.size(); inTensorId++) {
174	        const auto &inTensor = inTensors.at(inTensorId);
175	        if (inTensorId < emptyTensorPerms.size() && emptyTensorPerms.at(inTensorId) &&
176	            TensorCheck::IsEmptyTensor(inTensor)) {
177	            ATB_LOG(INFO) << GetLogPrefix() << "inTensor [" << inTensorId << "] is allowed empty";
178	            continue;
179	        }
180	        st = TensorCheck::CheckTensorShape(inTensor);
181	        if (st != NO_ERROR) {
182	            ATB_LOG(ERROR) << GetLogPrefix() << "inTensor [" << inTensorId
183	                           << "] CheckTensorShape failed. ErrorType: " << st;
184	            return st;
185	        }
186	    }
187	    return NO_ERROR;
188	}
