229	bool OperationBase::CheckIniMatch(const SVector<TensorDesc> &inTensorDescs) const
230	{
231	    if (!operationIr_) {
232	        return true;
233	    }
234	    if (!operationIr_->IsValid()) {
235	        ATB_LOG(ERROR) << GetLogPrefix() << "operationIr_ is invalid";
236	        return false;
237	    }
238	    const Mki::SVector<Mki::TensorInfoIr> &inTensorInfoIrs = operationIr_->GetInTensorInfoIrs();
239	    if (inTensorDescs.size() != inTensorInfoIrs.size()) {
240	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensorDescs size: " << inTensorDescs.size() << " is not equal "
241	                       << "inTensorInfoIrs size : " << inTensorInfoIrs.size();
242	        return false;
243	    }
244	    size_t supportSize = operationIr_->GetSupportSize();
245	    for (size_t supportIdx = 0; supportIdx < supportSize; supportIdx++) {
246	        if (CheckIniMatchSupportIdx(inTensorDescs, inTensorInfoIrs, supportIdx)) {
247	            ATB_LOG(INFO) << GetLogPrefix() << "dType and format matched. index: " << supportIdx;
248	            return true;
249	        }
250	    }
251	    return false;
252	}
