254	bool OperationBase::CheckIniMatch(const SVector<Tensor> &inTensors, const SVector<Tensor> &outTensors) const
255	{
256	    if (!operationIr_) {
257	        return true;
258	    }
259	    if (!operationIr_->IsValid()) {
260	        ATB_LOG(ERROR) << GetLogPrefix() << "operationIr_ is invalid";
261	        return false;
262	    }
263	    const Mki::SVector<Mki::TensorInfoIr> &inTensorInfoIrs = operationIr_->GetInTensorInfoIrs();
264	    const Mki::SVector<Mki::TensorInfoIr> &outTensorInfoIrs = operationIr_->GetOutTensorInfoIrs();
265	    if (inTensors.size() != inTensorInfoIrs.size()) {
266	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensors size: " << inTensors.size() << " is not equal "
267	                       << "inTensorInfoIrs size : " << inTensorInfoIrs.size();
268	        return false;
269	    }
270	    if (outTensors.size() != 0 && outTensors.size() != outTensorInfoIrs.size()) {
271	        ATB_LOG(ERROR) << GetLogPrefix() << "outTensors size: " << outTensors.size() << " is not equal "
272	                       << "outTensorInfoIrs size : " << outTensorInfoIrs.size();
273	        return false;
274	    }
275	    size_t supportSize = operationIr_->GetSupportSize();
276	    for (size_t supportIdx = 0; supportIdx < supportSize; supportIdx++) {
277	        if (CheckIniMatchSupportIdx(inTensors, inTensorInfoIrs, supportIdx) &&
278	            CheckIniMatchSupportIdx(outTensors, outTensorInfoIrs, supportIdx)) {
279	            ATB_LOG(INFO) << GetLogPrefix() << "dType and format matched. index: " << supportIdx;
280	            return true;
281	        }
282	    }
283	    return false;
284	}
