286	Status OperationBase::InferShapeCheck(const SVector<TensorDesc> &inTensorDescs) const
287	{
288	    ATB_LOG(INFO) << GetLogPrefix() << "infer shape start";
289	    for (size_t i = 0; i < inTensorDescs.size(); ++i) {
290	        ATB_LOG(INFO) << GetLogPrefix() << "infer shape inTensorDescs[" << i
291	                      << "]:" << TensorUtil::TensorDescToString(inTensorDescs.at(i));
292	    }
293	    if (inTensorDescs.size() != GetInputNum()) {
294	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensorDescs.size: " << inTensorDescs.size()
295	                       << " is not equal GetInputNum: " << GetInputNum();
296	        return ERROR_INVALID_IN_TENSOR_NUM;
297	    }
298	    Status st = CheckInTensor(inTensorDescs);
299	    if (st != NO_ERROR) {
300	        ATB_LOG(ERROR) << GetLogPrefix() << "Check in tensor desc fail, ErrorType: " << st;
301	        return st;
302	    }
303	    if (!CheckIniMatch(inTensorDescs)) {
304	        std::string actualInputs;
305	        for (size_t i = 0; i < inTensorDescs.size(); ++i) {
306	            if (i > 0) {
307	                actualInputs += ", ";
308	            }
309	            actualInputs += "inTensor" + std::to_string(i) + "(" + Mki::GetStrWithDType(inTensorDescs.at(i).dtype) +
310	                            ", " + Mki::GetStrWithFormat(inTensorDescs.at(i).format) + ")";
311	        }
312	        ATB_LOG(ERROR) << GetLogPrefix() << "CheckIniMatch Failed! Actual Inputs: " << actualInputs
313	                       << "\nSupported Combs: \n"
314	                       << operationIr_->GetCombString();
315	        return ERROR_INVALID_TENSOR_INI_MATCH;
316	    }
317	    if (!TensorCheck::CheckBF16(inTensorDescs)) {
318	        ATB_LOG(ERROR) << GetLogPrefix() << "Atlas inference products can not support bf16.";
319	        return ERROR_INVALID_TENSOR_DTYPE;
320	    }
321	    st = InferShapeCheckImpl(inTensorDescs);
322	    return st;
323	}
