369	Status OperationBase::CheckVariantPack(const VariantPack &variantPack) const
370	{
371	    if (variantPack.inTensors.size() != GetInputNum()) {
372	        ATB_LOG(ERROR) << GetLogPrefix() << "variantPack.inTensors.size: " << variantPack.inTensors.size()
373	                       << "is not equal GetInputNum: " << GetInputNum();
374	        return ERROR_INVALID_IN_TENSOR_NUM;
375	    }
376	    if (variantPack.outTensors.size() != GetOutputNum()) {
377	        ATB_LOG(ERROR) << GetLogPrefix() << "variantPack.outTensors.size: " << variantPack.outTensors.size()
378	                       << "is not equal GetOutputNum: " << GetOutputNum();
379	        return ERROR_INVALID_IN_TENSOR_NUM;
380	    }
381	    Status st = NO_ERROR;
382	    st = CheckInTensor(variantPack.inTensors);
383	    if (st != NO_ERROR) {
384	        return st;
385	    }
386	    st = CheckOutTensor(variantPack.outTensors);
387	    if (st != NO_ERROR) {
388	        return st;
389	    }
390	    if (!CheckIniMatch(variantPack.inTensors, variantPack.outTensors)) {
391	        std::string actualInputs;
392	        for (size_t i = 0; i < variantPack.inTensors.size(); ++i) {
393	            if (i > 0) {
394	                actualInputs += ", ";
395	            }
396	            actualInputs += "inTensor" + std::to_string(i) + "(" +
397	                            Mki::GetStrWithDType(variantPack.inTensors.at(i).desc.dtype) + ", " +
398	                            Mki::GetStrWithFormat(variantPack.inTensors.at(i).desc.format) + ")";
399	        }
400	        for (size_t i = 0; i < variantPack.outTensors.size(); ++i) {
401	            if (!actualInputs.empty() || i > 0) {
402	                actualInputs += ", ";
403	            }
404	            actualInputs += "outTensor" + std::to_string(i) + "(" +
405	                            Mki::GetStrWithDType(variantPack.outTensors.at(i).desc.dtype) + ", " +
406	                            Mki::GetStrWithFormat(variantPack.outTensors.at(i).desc.format) + ")";
407	        }
408	        ATB_LOG(ERROR) << GetLogPrefix() << "CheckIniMatch Failed! Actual Inputs: " << actualInputs
409	                       << "\nSupported Combs: \n"
410	                       << operationIr_->GetCombString();
411	        return ERROR_INVALID_TENSOR_INI_MATCH;
412	    }
413	    return NO_ERROR;
414	}
