416	Status OperationBase::SetupCheck(const VariantPack &variantPack, Context *context)
417	{
418	    Status st = CheckVariantPack(variantPack);
419	    if (st != NO_ERROR) {
420	        return st;
421	    }
422	    SVector<TensorDesc> inTensorDescs = {};
423	    SVector<TensorDesc> outTensorDescs = {};
424	    inTensorDescs.reserve(variantPack.inTensors.size());
425	    outTensorDescs.reserve(variantPack.outTensors.size());
426	    OperationUtil::InTensorsToInTensorDescs(variantPack.inTensors, inTensorDescs);
427	    OperationUtil::InTensorsToInTensorDescs(variantPack.outTensors, outTensorDescs);
428	    if (!TensorCheck::CheckBF16(inTensorDescs) || !TensorCheck::CheckBF16(outTensorDescs)) {
429	        ATB_LOG(ERROR) << GetLogPrefix() << "Atlas inference products can not support bf16.";
430	        return ERROR_INVALID_TENSOR_DTYPE;
431	    }
432	    st = SetupCheckImpl(variantPack.inTensors, variantPack.outTensors);
433	    if (st != NO_ERROR) {
434	        return st;
435	    }
436	
437	    if (!context) {
438	        ATB_LOG(ERROR) << GetLogPrefix() << "context is null, setup fail";
439	        return ERROR_INVALID_PARAM;
440	    }
441	
442	    runnerVariantPack_.context = dynamic_cast<ContextBase *>(context);
443	    if (!runnerVariantPack_.context) {
444	        ATB_LOG(ERROR) << GetLogPrefix() << "context is not ContextBase, setup fail";
445	        return ERROR_INVALID_PARAM;
446	    }
447	
448	    return NO_ERROR;
449	}
