520	Status OperationBase::SetupThrow(const VariantPack &variantPack, uint64_t &workspaceSize)
521	{
522	    Mki::Timer runnerCreateTimer;
523	    Status st = SetupThrowPrepare(workspaceSize, runnerVariantPack_.context);
524	    if (st != NO_ERROR) {
525	        return st;
526	    }
527	    GetOpSetupStatistic().runnerCreateTime += runnerCreateTimer.ElapsedMicroSecond();
528	
529	    InitRunnerVariantPack(variantPack);
530	    // step1 runner setup
531	    Mki::Timer runnerSetupTimer;
532	    if (!runner_) {
533	        ATB_LOG(ERROR) << GetLogPrefix() << "runner is null.";
534	        return ERROR_OPERATION_NULL_RUNNER;
535	    }
536	
537	    hostTilingBuffer_ = runnerVariantPack_.context->GetHostTilingBuffer();
538	    if (!hostTilingBuffer_) {
539	        ATB_LOG(ERROR) << GetLogPrefix() << "get host tiling buffer from contextbase is null";
540	        return ERROR_OUT_OF_HOST_MEMORY;
541	    }
542	    runnerVariantPack_.hostTilingBuffer = hostTilingBuffer_;
543	    runnerVariantPack_.tilingBufferSize = runnerVariantPack_.context->GetTilingBufferBlockSize();
544	#ifdef _DEBUG
545	    ATB_LOG(INFO) << GetLogPrefix()
546	                  << "get host tiling buffer from contextbase is:" << static_cast<void *>(hostTilingBuffer_)
547	                  << ", size:" << runnerVariantPack_.context->GetTilingBufferBlockSize();
548	#endif
549	
550	    st = runner_->Setup(runnerVariantPack_);
551	    GetOpSetupStatistic().runnerSetupTime += runnerSetupTimer.ElapsedMicroSecond();
552	    if (st != 0) {
553	        ATB_LOG(ERROR) << GetLogPrefix() << "runner setup fail";
554	        return st;
555	    }
556	
557	    // step2, get runner tiling buffer size
558	    runnerVariantPack_.tilingBufferSize =
559	        static_cast<uint64_t>(TensorUtil::AlignInt(runner_->GetTilingBufferSize(), WORKSPACE_ALIGN));
560	
561	    // step3, fill runner host tiling buffer
562	    FillHostTilingBuffer();
563	
564	    // step4, get runner workspasce and inter
565	    // 计算所有流的workspaceBufferSize
566	    runnerVariantPack_.workspaceBufferSize =
567	        static_cast<uint64_t>(TensorUtil::AlignInt(GetTotalWorkspaceBufferSize(), WORKSPACE_ALIGN));
568	
569	    runnerVariantPack_.intermediateBufferSize =
570	        static_cast<uint64_t>(TensorUtil::AlignInt(runner_->GetIntermediateBufferSize(), WORKSPACE_ALIGN));
571	
572	    workspaceSize = runnerVariantPack_.workspaceBufferSize + runnerVariantPack_.intermediateBufferSize;
573	    workspaceSize_ = workspaceSize;
574	
575	    ATB_LOG(INFO) << GetLogPrefix() << "setup success, workspaceSize:" << workspaceSize
576	                  << ", runner.tilingBufferSize:" << runnerVariantPack_.tilingBufferSize
577	                  << ", runner.workspaceBufferSize:" << runnerVariantPack_.workspaceBufferSize
578	                  << ", runner.intermediateBufferSize:" << runnerVariantPack_.intermediateBufferSize;
579	
580	    return st;
581	}
