716	Status OperationBase::CopyTilingToDevice()
717	{
718	    ContextBase *contextBase = runnerVariantPack_.context;
719	    if (runnerVariantPack_.tilingBufferSize > contextBase->GetTilingBufferBlockSize()) {
720	        ATB_LOG(ERROR) << GetLogPrefix() << "tilingSize is bigger than tilingBufferSize!";
721	        return ERROR_OUT_OF_HOST_MEMORY;
722	    }
723	
724	    if (runnerVariantPack_.tilingBufferSize == 0) {
725	        return NO_ERROR;
726	    }
727	
728	    aclrtStream executeStream = GetExecuteStream(runnerVariantPack_.context);
729	    aclrtStream tilingCopyStream = contextBase->GetAsyncTilingCopyStream();
730	    aclrtEvent tilingCopyEvent = nullptr;
731	    if (tilingCopyStream) {
732	        tilingCopyEvent = contextBase->GetAsyncTilingCopyEvent();
733	        ATB_LOG_IF(!tilingCopyEvent, ERROR) << GetLogPrefix() << "get copy event from contextbase fail";
734	    }
735	
736	    Status st = NO_ERROR;
737	    if (tilingCopyStream && tilingCopyEvent) {
738	        ATB_LOG(DEBUG) << GetLogPrefix() << "tiling copy stream is valid, use it to copy tiling to device";
739	        st = CopyHostTilingToDevice(tilingCopyStream);
740	        st = aclrtRecordEvent(tilingCopyEvent, tilingCopyStream) + st;
741	        st = aclrtStreamWaitEvent(executeStream, tilingCopyEvent) + st;
742	        st = aclrtResetEvent(tilingCopyEvent, executeStream) + st;
743	    } else {
744	        ATB_LOG(DEBUG) << GetLogPrefix() << "use execute stream to copy tiling to device";
745	        st = CopyHostTilingToDevice(executeStream);
746	    }
747	
748	    return st;
749	}
