751	template <typename TensorType>
752	Status OperationBase::ExecuteVariantPackInTensorCheck(const SVector<TensorType> &inTensors) const
753	{
754	    std::string Prefix = GetLogPrefix();
755	    if (inTensors.size() != runnerVariantPack_.inTensors.size()) {
756	        ATB_LOG(ERROR) << GetLogPrefix() << "execute inTensors.size:" << inTensors.size()
757	                       << " != setup inTensors.size:" << runnerVariantPack_.inTensors.size();
758	        return ERROR_INVALID_PARAM;
759	    }
760	    SVector<bool> emptyInTensorPerms = GetEmptyInTensorPermissions();
761	    for (size_t i = 0; i < inTensors.size(); i++) {
762	        const Tensor &variantPackInTensor = inTensors.at(i);
763	        if (Prefix.find("WithStride") == std::string::npos && // "WithStride" indicates non continuous tensors
764	            variantPackInTensor.dataSize != Utils::GetTensorSize(runnerVariantPack_.inTensors.at(i).desc)) {
765	            ATB_LOG(ERROR) << GetLogPrefix() << "execute variantPack.inTensors(" << i
766	                           << ").dataSize is Not equal to the setup dataSize";
767	            return ERROR_INVALID_PARAM;
768	        }
769	        if (i < emptyInTensorPerms.size() && emptyInTensorPerms.at(i) &&
770	            TensorCheck::IsEmptyTensor(variantPackInTensor)) {
771	            continue;
772	        }
773	        if (!variantPackInTensor.deviceData && !variantPackInTensor.hostData) {
774	            return ERROR_INVALID_PARAM;
775	        }
776	    }
777	    return NO_ERROR;
778	}
