826	Status OperationBase::ExecuteCheck(const VariantPack &variantPack, const uint8_t *workspace, uint64_t workspaceSize,
827	                                   Context *context)
828	{
829	    if (GetExecuteStream(runnerVariantPack_.context) == nullptr) {
830	        ATB_LOG(ERROR) << GetLogPrefix() << "execute stream is null";
831	        return ERROR_INVALID_PARAM;
832	    }
833	    if (context != runnerVariantPack_.context) {
834	        ATB_LOG(ERROR) << GetLogPrefix() << "execute context is same with setup context";
835	        return ERROR_INVALID_PARAM;
836	    }
837	
838	    if (!runner_) {
839	        ATB_LOG(ERROR) << GetLogPrefix() << "runner is null.";
840	        return ERROR_OPERATION_NULL_RUNNER;
841	    }
842	
843	    if (workspaceSize < workspaceSize_) {
844	        ATB_LOG(ERROR) << GetLogPrefix() << "execute workspaceSize:" << workspaceSize
845	                       << " < setup workspaceSize:" << workspaceSize_;
846	        return ERROR_INVALID_PARAM;
847	    }
848	
849	    if (workspaceSize_ != 0 && workspace == nullptr) {
850	        ATB_LOG(ERROR) << GetLogPrefix() << "execute workspace is can't be null when workspaceSize > 0";
851	        return ERROR_INVALID_PARAM;
852	    }
853	    if (variantPack.inTensors.size() > 0 || variantPack.outTensors.size() > 0) {
854	        Status st = ExecuteVariantPackCheck(variantPack);
855	        if (st != NO_ERROR) {
856	            ATB_LOG(ERROR) << GetLogPrefix() << "CheckExecuteVariantPack failed!";
857	            return st;
858	        }
859	    }
860	
861	    return NO_ERROR;
862	}
