942	Status OperationBase::GraphModePreLaunch(const VariantPack &variantPack, uint8_t *workspace, uint64_t workspaceSize,
943	                                         Context *context)
944	{
945	    Status st = NO_ERROR;
946	    lastWorkspaceAddr_ = reinterpret_cast<void *>(workspace);
947	    if (!isCaptured_) {
948	        argsBufferSize_ = runner_->GetArgsSize();
949	        if (deviceArgsBuffer_ == nullptr) {
950	            // 调用Context分配deviceArgsBuffer_
951	            deviceArgsBuffer_ = runnerVariantPack_.context->GetArgsDeviceBuffer(argsBufferSize_);
952	        }
953	
954	        if (hostArgsBuffer_ == nullptr) {
955	            // 调用Context分配hostArgsBuffer_
956	            hostArgsBuffer_ = runnerVariantPack_.context->GetArgsHostBuffer(argsBufferSize_);
957	        }
958	
959	        runnerVariantPack_.argsDeviceBuffer = reinterpret_cast<uint8_t *>(deviceArgsBuffer_);
960	        runnerVariantPack_.argsHostBuffer = reinterpret_cast<uint8_t *>(hostArgsBuffer_);
961	        st = EagerModePreLaunch(variantPack, workspace, workspaceSize, context);
962	        ATB_CHECK(st == 0, "EagerModePreLaunch failed!", return st);
963	        // 上述的preLaunch当前只做了地址更新及tiling拷贝，后续考虑改名。当前为保证已有代码的质量不修改原有流程，后续需要考虑EAGER_MODE与GRAPH_MODE的流程归纳与复用。
964	    } else {
965	        ATB_LOG(INFO) << GetLogPrefix() << "begin update tensor addr.";
966	        if (workspace == runnerVariantPack_.workspaceBuffer) {
967	            // 如果workspace地址没有变化，intermediateBuffer作为偏移量为0
968	            runnerVariantPack_.intermediateBuffer = nullptr;
969	        } else if (workspace > runnerVariantPack_.workspaceBuffer) {
970	            // 如果workspace发生了变化，计算workspace变化带来的偏移量时需要再加上workspaceBufferSize才是中间tensor对应内存的起始地址
971	            runnerVariantPack_.intermediateBuffer = workspace -
972	                                                    reinterpret_cast<uint64_t>(runnerVariantPack_.workspaceBuffer) +
973	                                                    runnerVariantPack_.workspaceBufferSize;
974	#ifdef _DEBUG
975	            ATB_LOG(INFO) << GetLogPrefix()
976	                          << "changing the old workspace: " << static_cast<void *>(runnerVariantPack_.workspaceBuffer)
977	                          << " to new workspace: " << static_cast<void *>(workspace)
978	                          << ", and the runnerVariantPack_.intermediateBuffer: "
979	                          << static_cast<void *>(runnerVariantPack_.intermediateBuffer);
980	#endif
981	            runnerVariantPack_.workspaceBuffer = workspace;
982	            // 刷新图中所有node的workpsaceBuffer
983	            st = runner_->UpdateWorkspaceBuffer(runnerVariantPack_);
984	        } else {
985	            runnerVariantPack_.intermediateBuffer = runnerVariantPack_.workspaceBuffer -
986	                                                    reinterpret_cast<uint64_t>(workspace) +
987	                                                    runnerVariantPack_.workspaceBufferSize;
988	#ifdef _DEBUG
989	            ATB_LOG(INFO) << GetLogPrefix()
990	                          << "changing the old workspace: " << static_cast<void *>(runnerVariantPack_.workspaceBuffer)
991	                          << " to new workspace: " << static_cast<void *>(workspace)
992	                          << ", and the runnerVariantPack_.intermediateBuffer: "
993	                          << static_cast<void *>(runnerVariantPack_.intermediateBuffer);
994	#endif
995	            runnerVariantPack_.workspaceBuffer = workspace;
996	            st = runner_->UpdateWorkspaceBuffer(runnerVariantPack_);
997	        }
998	        st = runner_->UpdateTensorAddr(runnerVariantPack_);
999	        ATB_CHECK(st == 0, GetLogPrefix() + "UpdateTensorAddr failed!", return st);
1000	        FillHostTilingBuffer();
1001	        st = CopyTilingToDevice();
1002	        ATB_CHECK(st == 0, GetLogPrefix() + "CopyTilingToDevice failed!", return st);
1003	    }
1004	    st = runner_->BuildArgs();
1005	    ATB_CHECK(st == 0, GetLogPrefix() + "BuildArgs failed!", return st);
1006	
1007	    st = CopyArgsToDevice(context);
1008	    ATB_CHECK(st == 0, GetLogPrefix() + "CopyArgsToDevice failed!", return st);
1009	
1010	    return st;
1011	}
