1069	Status OperationBase::GraphModeLaunch()
1070	{
1071	    Status st = NO_ERROR;
1072	    aclrtStream executeStream = GetExecuteStream(runnerVariantPack_.context);
1073	    if (streamStatus_ == ACL_MODEL_RI_CAPTURE_STATUS_ACTIVE) {
1074	        isCaptured_ = true;
1075	        st = EagerModeLaunch();
1076	        ATB_LOG_IF(st != 0, ERROR) << GetLogPrefix() << "EagerModeLaunch failed! ret:" << st;
1077	        return st;
1078	    }
1079	
1080	    if (!isCaptured_) {
1081	        st = aclmdlRICaptureBegin(executeStream, ACL_MODEL_RI_CAPTURE_MODE_GLOBAL);
1082	        ATB_LOG_IF(st != 0, ERROR) << GetLogPrefix() << "aclmdlRICaptureBegin failed! ret:" << st;
1083	        st = EagerModeLaunch();
1084	        ATB_LOG_IF(st != 0, ERROR) << GetLogPrefix() << "EagerModeLaunch failed! ret:" << st;
1085	        st = aclmdlRICaptureEnd(executeStream, &model_);
1086	        ATB_LOG_IF(st != 0, ERROR) << GetLogPrefix() << "aclmdlRICaptureEnd failed! ret:" << st;
1087	    }
1088	
1089	    isCaptured_ = true;
1090	    st = aclmdlRIExecuteAsync(model_, executeStream);
1091	    ATB_LOG_IF(st != 0, ERROR) << GetLogPrefix() << "aclmdlRIExecuteAsync failed! ret:" << st;
1092	    return st;
1093	}
