1095	Status OperationBase::Execute(const VariantPack &variantPack, uint8_t *workspace, uint64_t workspaceSize,
1096	                              Context *context)
1097	{
1098	    const uint64_t beginTime = GetSingleton<Mki::ProfilingFuncs>().GetProfilingLevel0Status() ?
1099	                                   GetSingleton<Mki::ProfilingFuncs>().ProfSysCycleTime() :
1100	                                   0;
1101	    ExecuteType executeType = context->GetExecuteType();
1102	    ProfilingFuncName profType = executeType == EXECUTE_NORMAL ?
1103	                                     OPERATION_EXECUTE :
1104	                                     (executeType == EXECUTE_PRELAUNCH ? OPERATION_PRELAUNCH : OPERATION_LAUNCH);
1105	    std::shared_ptr<MstxMemRegister> mstxMemRegister{nullptr};
1106	    if (workspaceSize != 0 && MstxMemRegister::IsMstxEnable()) {
1107	        mstxMemRegister = std::make_shared<MstxMemRegister>();
1108	        if (mstxMemRegister->MstxHeapRegister(workspace, workspaceSize) == NO_ERROR) {
1109	            runnerVariantPack_.mstxMemRegister = mstxMemRegister.get();
1110	            ATB_LOG(INFO) << GetLogPrefix() << "mstxMemHeapRegister success ";
1111	        }
1112	    }
1113	    Status st = NO_ERROR;
1114	    if (executeType == EXECUTE_NORMAL || executeType == EXECUTE_PRELAUNCH) {
1115	        st = PreLaunch(variantPack, workspace, workspaceSize, context);
1116	        if (st != NO_ERROR) {
1117	            ATB_LOG(ERROR) << GetLogPrefix() << "PreLaunch fail, error code: " << st;
1118	            return st;
1119	        }
1120	    }
1121	    if (executeType == EXECUTE_NORMAL || executeType == EXECUTE_LAUNCH) {
1122	        st = Launch();
1123	        if (st != NO_ERROR) {
1124	            ATB_LOG(ERROR) << GetLogPrefix() << "Launch fail, error code: " << st;
1125	            return st;
1126	        }
1127	    }
1128	    if (GetSingleton<Mki::ProfilingFuncs>().GetProfilingLevel0Status()) {
1129	        ReportApiInfo(beginTime, profType);
1130	    }
1131	    GetOpExecuteStatistic().Reset();
1132	    return st;
1133	}
