1154	
1155	        ATB_LOG(DEBUG) << GetLogPrefix() << "copy host tiling to device start, totalTilingBufferSize:"
1156	                       << runnerVariantPack_.tilingBufferSize;
1157	        Mki::Timer timer;
1158	        if (hostTilingBuffer_ == nullptr) {
1159	            ATB_LOG(ERROR) << GetLogPrefix() << "host tiling buffer is null!";
1160	            return ERROR_OUT_OF_HOST_MEMORY;
1161	        }
1162	        int ret = 0;
1163	        if (runnerVariantPack_.context->GetLaunchMode() == GRAPH_LAUNCH_MODE && !isCaptured_) {
1164	            ret = aclrtMemcpy(runnerVariantPack_.tilingBuffer, runnerVariantPack_.tilingBufferSize, hostTilingBuffer_,
1165	                              runnerVariantPack_.tilingBufferSize, ACL_MEMCPY_HOST_TO_DEVICE);
1166	        } else {
1167	            ret = aclrtMemcpyAsync(runnerVariantPack_.tilingBuffer, runnerVariantPack_.tilingBufferSize,
1168	                                   hostTilingBuffer_, runnerVariantPack_.tilingBufferSize, ACL_MEMCPY_HOST_TO_DEVICE,
1169	                                   stream);
1170	        }
1171	
1172	        GetOpExecuteStatistic().tillingCopyTime += timer.ElapsedMicroSecond();
1173	        if (ret != 0) {
1174	            ATB_LOG(ERROR) << GetLogPrefix() << "copy host tiling to device fail, ret:" << ret;
1175	            return ERROR_RT_FAIL;
1176	        }
1177	        ATB_LOG(DEBUG) << GetLogPrefix() << "copy host tiling to device success";
1178	    } else {
1179	        UpdateCurrentOpTiling(nullptr, 0);
1180	    }
1181	    return NO_ERROR;
1182	}
