    bool PerTokenXWeightDimNumCheck(const TensorDesc &xTensorDesc, const TensorDesc &weightTensorDesc) const;

private:
    infer::LinearParam param_;
    MatmulCommonCheckParam commonCheckParam_;
};
} // namespace atb
#endif

