36	bool MatmulParamCheck(const infer::LinearParam &opParam, ExternalError &error)
37	{
38	    if (opParam.quantMode != atb::infer::LinearParam::QUANT_UNDEFINED) {
39	        error.errorData = OperationUtil::ConcatInfo(error.errorData, "quantMode = ", opParam.quantMode);
40	        error.errorDesc = "QuantMode is not the default value. When outDataType is undefind, quantMode needs to be undefind.";
41	        error.solutionDesc = "Please check the quantMode value of input params.";
42	        ATB_LOG(ERROR) << error;
43	        return false;
44	    }
45	    if (opParam.enAccum) {
46	        error.errorData = OperationUtil::ConcatInfo(error.errorData, "enAccum = ", opParam.enAccum);
47	        if (!GetSingleton<Config>().Is910B()) {
48	            error.errorDesc = "Platform is not Atlas 800I A2 inference product, enAccum should be false,";
49	            error.solutionDesc = "Please check the platform and value of input params.";
50	            ATB_LOG(ERROR) << error;
51	            return false;
52	        }
53	        if (opParam.hasBias) {
54	            error.errorDesc = "enAccum and hasBias can not both be true!";
55	            error.errorData = OperationUtil::ConcatInfo(error.errorData, ", hasBias = ", opParam.hasBias);
56	            ATB_LOG(ERROR) << error;
57	            return false;
58	        }
59	    }
60	    return true;
61	}
62	
63	bool MatmulEinParamCheck(const infer::LinearParam &opParam, ExternalError &error)
64	{
65	    if (opParam.enAccum) {
66	        error.errorDesc = "When MatmulEin is used, enAccum should be false,";
67	        error.solutionDesc = "Please check the value of input params.";
68	        ATB_LOG(ERROR) << error;
69	        return false;
70	    } else if (opParam.transposeA) {
71	        error.errorDesc = "When MatmulEin is used, transposeA should be false,";
72	        error.solutionDesc = "Please check the value of input params.";
73	        ATB_LOG(ERROR) << error;
74	        return false;
75	    } else if (opParam.hasBias) {
76	        error.errorDesc = "When MatmulEin is used, hasBias should be false,";
77	        error.solutionDesc = "Please check the value of input params.";
78	        ATB_LOG(ERROR) << error;
79	        return false;
80	    } else if (opParam.outDataType != ACL_DT_UNDEFINED) {
81	        error.errorDesc = "When MatmulEin is used, outDataType should be ACL_DT_UNDEFINED,";
82	        error.solutionDesc = "Please check the value of input params.";
83	        ATB_LOG(ERROR) << error;
84	        return false;
85	    }
86	    return true;
87	}
88	
89	bool MatmulDequantFloat16ParamCheck(const infer::LinearParam &opParam, ExternalError &error)
90	{
91	    if (!GetSingleton<Config>().Is910B()) {
92	        error.errorDesc = "Platform is not Atlas 800I A2 inference product, outDataType is ACL_FLOAT16, ";
93	        error.solutionDesc = "Please check the platform and value of input params.";
94	        if (opParam.transposeA) {
95	            error.errorDesc = error.errorDesc + "transposeA should be false.";
96	            error.errorData = OperationUtil::ConcatInfo(error.errorData, ", transposeA = ", opParam.transposeA);
97	            ATB_LOG(ERROR) << error;
98	            return false;
99	        }
100	        if (!opParam.transposeB) {
101	            error.errorDesc = error.errorDesc + "transposeB should be true.";
102	            error.errorData = OperationUtil::ConcatInfo(error.errorData, ", transposeB = ", opParam.transposeB);
103	            ATB_LOG(ERROR) << error;
104	            return false;
105	        }
106	        if (!opParam.hasBias && !GetSingleton<Config>().Is310B()) {
107	            error.errorDesc = error.errorDesc + "hasBias should be true.";
108	            error.errorData = OperationUtil::ConcatInfo(error.errorData, ", hasBias = ", opParam.hasBias);
109	            ATB_LOG(ERROR) << error;
110	            return false;
111	        }
112	        if (opParam.quantMode == infer::LinearParam::PER_TOKEN) {
113	            error.errorDesc = error.errorDesc + "quantMode should be QUANT_UNDEFINED or PER_CHANNEL.";
114	            error.errorData = OperationUtil::ConcatInfo(error.errorData, ", quantMode = ", opParam.quantMode);
115	            ATB_LOG(ERROR) << error;
116	            return false;
117	        }
118	    } else if (opParam.quantMode == infer::LinearParam::PER_TOKEN && opParam.hasBias) {
119	        error.errorDesc = "PER_TOKEN quantMode is not supported when hasBias is true";
120	        error.solutionDesc = "Please check the value of input params.";
121	        ATB_LOG(ERROR) << error;
122	        return false;
123	    }
124	    return true;
125	}
126	
127	bool MatmulDequantBf16ParamCheck(const infer::LinearParam &opParam, ExternalError &error)
128	{
129	    (void)opParam;
130	    if (!GetSingleton<Config>().Is910B()) {
131	        error.errorDesc = "Platform is not Atlas 800I A2 inference product, outDataType should not be ACL_BF16.";
132	        error.solutionDesc = "Please check the platform and value of input params.";
133	        ATB_LOG(ERROR) << error;
134	        return false;
135	    } else if (opParam.quantMode == infer::LinearParam::PER_TOKEN && opParam.hasBias) {
136	        error.errorDesc = "PER_TOKEN quantMode is not supported when hasBias is true";
137	        error.solutionDesc = "Please check the value of input params.";
138	        ATB_LOG(ERROR) << error;
139	        return false;
140	    }
141	    return true;
142	}
143	
144	bool MatmulUndefindCheck(const infer::LinearParam &opParam, ExternalError &error)
145	{
146	    switch (opParam.outDataType) {
147	        case ACL_DT_UNDEFINED:
148	            {
149	                if (!MatmulParamCheck(opParam, error)) {
150	                    return false;
151	                }
152	                break;
153	            }
154	        case ACL_FLOAT16:
155	            {
156	                if (opParam.enAccum) {
157	                    error.errorDesc = "outDataType is not ACL_DT_UNDEFINED, enAccum should be false.";
158	                    error.errorData = OperationUtil::ConcatInfo(error.errorData, ", enAccum = ", opParam.enAccum);
159	                    ATB_LOG(ERROR) << error;
160	                    return false;
161	                }
162	                if (!MatmulDequantFloat16ParamCheck(opParam, error)) {
163	                    return false;
164	                }
165	                break;
166	            }
167	        case ACL_BF16:
168	            {
169	                if (opParam.enAccum) {
170	                    error.errorDesc = "outDataType is not ACL_DT_UNDEFINED, enAccum should be false.";
171	                    error.errorData = OperationUtil::ConcatInfo(error.errorData, ", enAccum = ", opParam.enAccum);
172	                    ATB_LOG(ERROR) << error;
173	                    return false;
174	                }
175	                if (!MatmulDequantBf16ParamCheck(opParam, error)) {
176	                    return false;
177	                }
178	                break;
179	            }
180	        default:
181	            {
182	                error.errorDesc = "outDataType should be ACL_DT_UNDEFINED/ACL_FLOAT16/ACL_BF16.";
183	                ATB_LOG(ERROR) << error;
184	                return false;
185	            }
186	    }
187	    return true;
188	}
189	
190	bool MatmulUndefindCheck950(const infer::LinearParam &opParam, ExternalError &error)
191	{
192	    if (opParam.enAccum) {
193	        error.errorDesc = "On 950, enAccum should be false.";
194	        error.solutionDesc = "Please check the value of input params.";
195	        ATB_LOG(ERROR) << error;
196	        return false;
197	    }
198	    switch (opParam.outDataType) {
199	        case ACL_DT_UNDEFINED:
200	            if (opParam.quantMode != infer::LinearParam::QUANT_UNDEFINED) {
201	                error.errorDesc = "On 950, when outDataType is undefind, quantMode should be QUANT_UNDEFINED.";
202	                error.solutionDesc = "Please check the value of input params.";
203	                ATB_LOG(ERROR) << error;
204	                return false;
205	            }
206	            break;
207	        case ACL_FLOAT16:
208	        case ACL_BF16:
209	            if (opParam.quantMode == infer::LinearParam::PER_TOKEN && opParam.hasBias) {
210	                error.errorDesc = "PER_TOKEN quantMode is not supported when hasBias is true";
211	                error.solutionDesc = "Please check the value of input params.";
212	                ATB_LOG(ERROR) << error;
213	                return false;
214	            }
215	            break;
216	        default:
217	            error.errorDesc = "outDataType should be ACL_DT_UNDEFINED/ACL_FLOAT16/ACL_BF16.";
218	            ATB_LOG(ERROR) << error;
219	            return false;
220	    }
221	    return true;
222	}
223	
224	template <> Status CreateOperation(const infer::LinearParam &opParam, Operation **operation)
225	{
226	    if (operation == nullptr) {
227	        return ERROR_INVALID_PARAM;
228	    }
229	    OP_PARAM_RSV_CHECK(opParam);
230	
231	    if (Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
232	        if (LinearAclnnRunner::LoadAclnnFuncs() != NO_ERROR) {
233	            ATB_LOG(ERROR) << "Load aclnn function failed, please check your CANN version.";
234	            return ERROR_CANN_ERROR;
235	        }
236	        if (LinearEinsumAclnnRunner::LoadAclnnFuncs() != NO_ERROR) {
237	            ATB_LOG(ERROR) << "Load aclnn function failed, please check your CANN version.";
238	            return ERROR_CANN_ERROR;
239	        }
240	        if (LinearDequantAclnnRunner::LoadAclnnFuncs() != NO_ERROR) {
241	            ATB_LOG(ERROR) << "Load dequant aclnn function failed, please check your CANN version.";
242	            return ERROR_CANN_ERROR;
243	        }
244	
245	        ExternalError error;
246	        error.errorType = ERROR_INVALID_PARAM;
247	        error.errorData = OperationUtil::ConcatInfo("outDataType = ", opParam.outDataType);
248	        error.solutionDesc = "Please check the value of input params.";
249	
250	        if (opParam.matmulType == infer::LinearParam::MATMUL_EIN_SUM) {
251	            if (!MatmulEinParamCheck(opParam, error)) {
252	                return ERROR_INVALID_PARAM;
253	            }
254	        } else if (opParam.matmulType == infer::LinearParam::MATMUL_UNDEFINED) {
255	            if (!MatmulUndefindCheck950(opParam, error)) {
256	                return ERROR_INVALID_PARAM;
257	            }
258	        } else {
259	            error.errorDesc = "matmulType uses an nonexistent type.";
260	            error.errorData = OperationUtil::ConcatInfo(error.errorData, ", matmulType = ", opParam.matmulType);
261	            ATB_LOG(ERROR) << error;
262	            return ERROR_INVALID_PARAM;
263	        }
264	
265	        *operation = new (std::nothrow) LinearOperation(opParam);
266	        if (*operation == nullptr) {
267	            ATB_LOG(ERROR) << "failed to new operation";
268	            return ERROR_OUT_OF_HOST_MEMORY;
269	        }
270	        return NO_ERROR;
271	    }
272	
273	    ExternalError error;
274	    error.errorType = ERROR_INVALID_PARAM;
275	    error.errorData = OperationUtil::ConcatInfo("outDataType = ", opParam.outDataType);
276	    error.solutionDesc = "Please check the value of input params.";
277	    if (opParam.matmulType == infer::LinearParam::MATMUL_EIN_SUM) {
278	        if (!MatmulEinParamCheck(opParam, error)) {
279	            return ERROR_INVALID_PARAM;
280	        }
281	        if (!GetSingleton<Config>().Is910B()) {
282	            error.errorDesc = "Platform is not Atlas 800I A2 inference product, MatmulType should be 0,";
283	            error.solutionDesc = "Please check the platform and value of input params.";
284	            ATB_LOG(ERROR) << error;
285	            return ERROR_INVALID_PARAM;
286	        }
287	    } else if (opParam.matmulType == infer::LinearParam::MATMUL_UNDEFINED) {
288	        if (!MatmulUndefindCheck(opParam, error)) {
289	            return ERROR_INVALID_PARAM;
290	        }
291	    } else {
292	        error.errorDesc = "matmulType uses an nonexistent type.";
293	        error.errorData = OperationUtil::ConcatInfo(error.errorData, ", matmulType = ", opParam.matmulType);
294	
295	        ATB_LOG(ERROR) << error;
296	        return ERROR_INVALID_PARAM;
297	    }
298	
299	    *operation = new (std::nothrow) LinearOperation(opParam);
300	    if (*operation == nullptr) {
301	        ATB_LOG(ERROR) << "failed to new operation";
302	        return ERROR_OUT_OF_HOST_MEMORY;
303	    }
304	    return NO_ERROR;
305	}
306	
307	LinearOperation::LinearOperation(const infer::LinearParam &param) : OperationBase("LinearOperation"), param_(param)
308	{
309	    commonCheckParam_ = param_;
310	    std::stringstream opIrKey;
311	    bool is950 = Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950;
312	    opIrKey << "LinearOperationMatmul";
313	    if (param_.matmulType == infer::LinearParam::MATMUL_EIN_SUM) {
314	        opIrKey << "EinSum";
315	        opIrKey << (param_.hasBias ? "ElewiseAdd" : "");
316	    } else if (param_.outDataType == ACL_DT_UNDEFINED) {
317	        if (param_.enAccum) {
318	            opIrKey << "Accum";
319	        } else {
320	            opIrKey << (param_.hasBias ? "WithBias" : "");
321	            opIrKey << (GetSingleton<Config>().Is910B() ? "Atlas800IA2" : "NotAtlas800IA2");
322	        }
323	    } else {
324	        opIrKey << (param_.hasBias ? "DequantWithBias" : "Dequant");
325	        if (param_.quantMode == infer::LinearParam::PER_TOKEN) {
326	            opIrKey << "PerToken";
327	        }
328	        if (param_.outDataType == ACL_FLOAT16) {
329	            opIrKey << "Float16";
330	            opIrKey << (GetSingleton<Config>().Is910B()                   ? "Atlas800IA2" :
331	                        GetSingleton<Config>().Is910A() && param_.hasBias ? "AtlasTrain" :
332	                                                                            "NotAtlas800IA2");
333	        } else if (param_.outDataType == ACL_BF16) {
334	            opIrKey << "Bf16";
335	            opIrKey << (GetSingleton<Config>().Is910B() ? "Atlas800IA2" : "NotAtlas800IA2");
336	        }
337	    }
338	    operationIr_ = GetSingleton<AtbOperationIrCfg>().GetOperationIr(opIrKey.str());
339	    if (is950) {
340	        if (param_.outDataType != ACL_DT_UNDEFINED) {
341	            std::stringstream opIrKey950;
342	            opIrKey950 << "LinearOperationMatmul";
343	            opIrKey950 << (param_.hasBias ? "DequantWithBias" : "Dequant");
344	            if (param_.quantMode == infer::LinearParam::PER_TOKEN) {
345	                opIrKey950 << "PerToken";
346	            }
347	            if (param_.outDataType == ACL_FLOAT16) {
348	                opIrKey950 << "Float16Ascend950";
349	            } else if (param_.outDataType == ACL_BF16) {
350	                opIrKey950 << "Bf16Ascend950";
351	            }
352	            operationIr_ = GetSingleton<AtbOperationIrCfg>().GetOperationIr(opIrKey950.str());
353	        } else if (param_.matmulType == infer::LinearParam::MATMUL_EIN_SUM) {
