522	Status LinearOperation::BiasCheck(const TensorDesc &biasTensorDesc, const TensorDesc &weightTensorDesc) const
523	{
524	    ExternalError error;
525	
526	    if (biasTensorDesc.shape.dimNum != 1 && biasTensorDesc.shape.dimNum != DIM_NUM_2) {
527	        error.errorType = ERROR_INVALID_TENSOR_DIM_NUM;
528	        error.errorDesc = "inTensor2 dim num should be 1 or 2,";
529	        error.errorData = OperationUtil::ConcatInfo("inTensor2 dimNum = ", biasTensorDesc.shape.dimNum);
530	        error.solutionDesc = "Please check shape of inTensor2.";
531	        ATB_LOG(ERROR) << GetLogPrefix() << error;
532	        return error.errorType;
533	    }
534	
535	    error.errorType = ERROR_INVALID_TENSOR_DIM;
536	    int64_t biasBatch = biasTensorDesc.shape.dimNum == 1 ? 1 : biasTensorDesc.shape.dims[0];
537	    int64_t weightBatch = OperationUtil::GetTensorBatch(weightTensorDesc, atb::infer::LinearParam::MATMUL_UNDEFINED);
538	    if (biasBatch != weightBatch) {
539	        error.errorDesc = "value of inTensor2 batch and value of inTensor1 batch should be equal,";
540	        error.errorData =
541	            OperationUtil::ConcatInfo("inTensor2 batch = ", biasBatch, ", inTensor1 batch = ", weightBatch);
542	        error.solutionDesc = "Please check the shape of inTensors.";
543	        ATB_LOG(ERROR) << GetLogPrefix() << error;
544	        return error.errorType;
545	    }
546	
547	    int64_t biasN = biasTensorDesc.shape.dims[biasTensorDesc.shape.dimNum - 1];
548	    int64_t weightN = OperationUtil::GetYTensorN(weightTensorDesc, param_.transposeB);
549	    if (biasN != weightN) {
550	        error.errorDesc = "value of inTensor2 n and value of inTensor1 n should be equal,";
551	        error.errorData = OperationUtil::ConcatInfo("inTensor2 n = ", biasN, ", inTensor1 n = ", weightN);
552	        error.solutionDesc = "Please check the shape of inTensors.";
553	        ATB_LOG(ERROR) << GetLogPrefix() << error;
554	        return error.errorType;
555	    }
556	    return NO_ERROR;
557	}
