719	bool LinearOperation::XWeightDimNumCheck(const TensorDesc &xTensorDesc, const TensorDesc &weightTensorDesc) const
720	{
721	    ExternalError error;
722	    error.errorType = ERROR_INVALID_TENSOR_DIM_NUM;
723	    error.solutionDesc = "Please check format and shape of inTensors.";
724	
725	    if (xTensorDesc.shape.dimNum != DIM_NUM_2 && xTensorDesc.shape.dimNum != DIM_NUM_3) {
726	        error.errorDesc = "inTensor0 dim num should be 2 or 3,";
727	        error.errorData = OperationUtil::ConcatInfo("inTensor0 dimNum = ", xTensorDesc.shape.dimNum);
728	        ATB_LOG(ERROR) << GetLogPrefix() << error;
729	        return false;
730	    }
731	
732	    if (weightTensorDesc.format == ACL_FORMAT_ND) {
733	        if (param_.matmulType == infer::LinearParam::MATMUL_EIN_SUM && weightTensorDesc.shape.dimNum != DIM_NUM_3) {
734	            error.errorDesc = "When EIN is used inTensor1 dim num should be 3,";
735	            error.errorData = OperationUtil::ConcatInfo("inTensor1 dimNum = ", weightTensorDesc.shape.dimNum);
736	            ATB_LOG(ERROR) << GetLogPrefix() << error;
737	            return false;
738	        } else if (weightTensorDesc.shape.dimNum != DIM_NUM_2 && weightTensorDesc.shape.dimNum != DIM_NUM_3) {
739	            error.errorDesc = "inTensor1 dim num should be 2 or 3,";
740	            error.errorData = OperationUtil::ConcatInfo("inTensor1 dimNum = ", weightTensorDesc.shape.dimNum);
741	            ATB_LOG(ERROR) << GetLogPrefix() << error;
742	            return false;
743	        }
744	    } else if (weightTensorDesc.format == ACL_FORMAT_FRACTAL_NZ) {
745	        if (param_.matmulType == infer::LinearParam::MATMUL_EIN_SUM && weightTensorDesc.shape.dimNum != DIM_NUM_4) {
746	            error.errorDesc = "When EIN is used inTensor1 dim num should be 4,";
747	            error.errorData = OperationUtil::ConcatInfo("inTensor1 dimNum = ", weightTensorDesc.shape.dimNum);
748	            ATB_LOG(ERROR) << GetLogPrefix() << error;
749	            return false;
750	        } else if (weightTensorDesc.shape.dimNum != DIM_NUM_2 && weightTensorDesc.shape.dimNum != DIM_NUM_3 &&
751	                   weightTensorDesc.shape.dimNum != DIM_NUM_4) {
752	            error.errorDesc = "inTensor1 dim num should be 2 or 3 or 4,";
753	            error.errorData = OperationUtil::ConcatInfo("inTensor1 dimNum = ", weightTensorDesc.shape.dimNum);
754	            ATB_LOG(ERROR) << GetLogPrefix() << error;
755	            return false;
756	        }
757	    }
758	    if (xTensorDesc.shape.dimNum == DIM_NUM_2 && weightTensorDesc.shape.dimNum == DIM_NUM_3) {
759	        error.errorDesc = "inTensor1 dim num is 3, inTensor0 dim num should not be 2,";
760	        error.errorData =
761	            OperationUtil::ConcatInfo("enAccum = ", param_.enAccum, ", inTensor0 dimNum = ", xTensorDesc.shape.dimNum,
762	                                      ", inTensor1 dimNum = ", weightTensorDesc.shape.dimNum);
763	        ATB_LOG(ERROR) << GetLogPrefix() << error;
764	        return false;
765	    }
766	    if (!PerTokenXWeightDimNumCheck(xTensorDesc, weightTensorDesc)) {
767	        return false;
768	    }
769	    if (Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
770	        bool isDequant = param_.outDataType != ACL_DT_UNDEFINED;
771	        if (!isDequant && xTensorDesc.shape.dimNum == DIM_NUM_3 && weightTensorDesc.shape.dimNum == DIM_NUM_3 &&
772	            param_.hasBias) {
773	            ATB_LOG(ERROR) << GetLogPrefix() << 
774	                "On 950, if hasBias is true, inTensor0 and inTensor1 dim num should not be 3 at the same time";
775	            return false;
776	        }
777	        if (!isDequant && (weightTensorDesc.shape.dimNum == DIM_NUM_3 ||
778	             (weightTensorDesc.shape.dimNum == DIM_NUM_4 && weightTensorDesc.shape.dims[0] != 1)) &&
779	            param_.hasBias) {
780	            ATB_LOG(ERROR)
781	                << GetLogPrefix()
782	                << "On 950, if hasBias is true, inTensor1 not support batch";
783	            return false;
784	        }
785	        if (isDequant && param_.quantMode != infer::LinearParam::PER_TOKEN) {
786	            int64_t weightBatch = OperationUtil::GetTensorBatch(weightTensorDesc,
787	                                                                infer::LinearParam::MATMUL_UNDEFINED);
788	            if (weightBatch > 1) {
789	                ATB_LOG(ERROR) << GetLogPrefix()
790	                    << "On 950, dequant per-channel not support weight batch > 1";
791	                return false;
792	            }
793	        }
794	    }
795	    return true;
796	}
797	
798	bool LinearOperation::PerTokenXWeightDimNumCheck(const TensorDesc &xTensorDesc, const TensorDesc &weightTensorDesc) const
799	{
800	    ExternalError error;
801	    error.errorType = ERROR_INVALID_TENSOR_DIM_NUM;
802	    error.solutionDesc = "Please check format and shape of inTensors.";
803	    if (param_.quantMode == infer::LinearParam::PER_TOKEN && xTensorDesc.shape.dimNum == DIM_NUM_3 && weightTensorDesc.shape.dimNum == DIM_NUM_2) {
804	        error.errorDesc = "When quantMode is PER_TOKEN and inTensor0 dim num is 3, inTensor1 dim num cannot be 2,";
805	        error.errorData = OperationUtil::ConcatInfo("quantMode = ", param_.quantMode, ", inTensor0 dimNum = ", xTensorDesc.shape.dimNum,
806	                                                    ", inTensor1 dimNum = ", weightTensorDesc.shape.dimNum);
807	        ATB_LOG(ERROR) << GetLogPrefix() << error;
808	        return false;
809	    }
810	    return true;
811	}
812	
813	bool LinearOperation::XWeightBatchCheck(const TensorDesc &xTensorDesc, const TensorDesc &weightTensorDesc) const
814	{
815	    ExternalError error;
816	    error.errorType = ERROR_INVALID_TENSOR_DIM;
817	    int64_t xBatch = OperationUtil::GetTensorBatch(xTensorDesc, param_.matmulType);
818	    int64_t weightBatch = OperationUtil::GetTensorBatch(weightTensorDesc, atb::infer::LinearParam::MATMUL_UNDEFINED);
819	    if (xBatch != weightBatch) {
820	        if (param_.transposeA) {
821	            error.errorDesc = "transposeA is true, values of inTensor0 batch and inTensor1 batch should be equal,";
822	            error.errorData = OperationUtil::ConcatInfo(
823	                "transposeA: ", param_.transposeA, ", inTensor0 batch = ", xBatch, ", inTensor1 batch = ", weightBatch);
824	            error.solutionDesc = "Please check the value of params and shape of inTensors.";
825	            ATB_LOG(ERROR) << GetLogPrefix() << error;
826	            return false;
827	        }
828	        if (weightTensorDesc.shape.dimNum == DIM_NUM_3) {
829	            error.errorDesc = "inTensor1 dimNum is 3, values of inTensor0 batch and inTensor1 batch should be equal,";
830	            error.errorData =
831	                OperationUtil::ConcatInfo("inTensor1 dimNum = ", weightTensorDesc.shape.dimNum,
832	                                          "inTensor0 batch = ", xBatch, ", inTensor1 batch = ", weightBatch);
833	            error.solutionDesc = "Please check the shape of inTensors.";
834	            ATB_LOG(ERROR) << GetLogPrefix() << error;
835	            return false;
836	        }
837	        if (weightBatch != 1) {
838	            error.errorDesc =
839	                "inTensor1 dimNum is not 3, value of inTensor1 batch should be 1 or equal to value of inTensor0 batch,";
840	            error.errorData =
841	                OperationUtil::ConcatInfo("inTensor1 dimNum = ", weightTensorDesc.shape.dimNum,
842	                                          "inTensor0 batch = ", xBatch, ", inTensor1 batch = ", weightBatch);
843	            error.solutionDesc = "Please check the shape of inTensors.";
844	            ATB_LOG(ERROR) << GetLogPrefix() << error;
845	            return false;
846	        }
847	    }
848	    return true;
849	}
850	
851	bool LinearOperation::XWeightKEqualCheck(const TensorDesc &xTensorDesc, const TensorDesc &weightTensorDesc) const
852	{
853	    int64_t xK = OperationUtil::GetXTensorK(xTensorDesc, param_.transposeA);
854	    int64_t weightK = OperationUtil::GetYTensorK(weightTensorDesc, param_.transposeB);
855	    if (xK == weightK) {
856	        return true;
857	    }
858	    ExternalError error;
859	    error.errorType = ERROR_INVALID_TENSOR_DIM;
860	    error.errorDesc = "value of inTensor0 k and value of inTensor1 k should be equal,";
861	    error.errorData = OperationUtil::ConcatInfo("inTensor0 k = ", xK, ", inTensor1 k = ", weightK);
862	    error.solutionDesc = "Please check the shape of inTensors.";
863	    ATB_LOG(ERROR) << GetLogPrefix() << error;
864	    return false;
865	}
866	
867	bool LinearOperation::WeightAlignCheck(const TensorDesc &weightTensorDesc, int64_t align) const
868	{
869	    if (weightTensorDesc.shape.dimNum != DIM_NUM_4) {
870	        return true;
871	    }
872	    ExternalError error;
873	    error.errorType = ERROR_INVALID_TENSOR_DIM;
874	    int64_t dim2 = weightTensorDesc.shape.dims[DIM_2];
875	    if (dim2 % DEFAULT_ALIGN != 0) {
876	        error.errorDesc = "inTensor1 dim2 should be divisible by 16,";
877	        error.errorData = OperationUtil::ConcatInfo("inTensor1 dim2 = ", dim2);
878	        error.solutionDesc = "Please check the shape of inTensors.";
879	        ATB_LOG(ERROR) << GetLogPrefix() << error;
880	        return false;
881	    }
882	    int64_t dim3 = weightTensorDesc.shape.dims[DIM_3];
883	    if (dim3 != align) {
884	        error.errorDesc = OperationUtil::ConcatInfo("inTensor1 dim3 should be ", align, ",");
885	        error.errorData = OperationUtil::ConcatInfo("inTensor1 dim3 = ", dim3);
886	        error.solutionDesc = "Please check the value of params and shape of inTensors.";
887	        ATB_LOG(ERROR) << GetLogPrefix() << error;
888	        return false;
889	    }
890	    return true;
891	}
892	} // namespace atb

